import { describe, expect, it } from 'vitest'
import { searchCommands } from './paletteSearch'
import { SKETCH_CASES, SKETCH_COMMANDS, STUDIO_CASES, STUDIO_COMMANDS } from './paletteRanking.fixture'

// The ranking is freeshape/ui/palette.py `search_commands`. The fixture holds that function's answers for a table of queries over
// the desktop's own Part Studio and sketch command lists (paletteRanking.fixture.ts, generated by running it).
describe('searchCommands', () => {
  it.each(STUDIO_CASES)('Part Studio: %j lists what search_commands lists, in its order', (query, names) => {
    expect(searchCommands(STUDIO_COMMANDS, query).map((c) => c.name)).toEqual(names)
  })

  it.each(SKETCH_CASES)('sketch: %j lists what search_commands lists, in its order', (query, names) => {
    expect(searchCommands(SKETCH_COMMANDS, query).map((c) => c.name)).toEqual(names)
  })

  it('a name that starts with the first word comes first, then names holding every word, then names and keywords, then the rest', () => {
    const c = (name: string, keywords = '', description = '', group = '') => ({ name, keywords, description, group })
    const list = [c('Zed', '', 'about round things'), c('Round off'), c('Soften', 'round'), c('Anything', '', '', 'Round')]
    expect(searchCommands(list, 'round').map((x) => x.name)).toEqual(['Round off', 'Soften', 'Zed', 'Anything'])
    expect(searchCommands(list, '  ').length).toBe(4)
    expect(searchCommands(list, 'ROUND off').map((x) => x.name)).toEqual(['Round off'])
  })
})
